-- AU-hartland P1 · S1.3 — R-A, the automation extension's recon (contracts §5): read-only, printed by
-- run-automation.sh after a build and by run-recon.sh (`just automation-recon`), which diffs it against the committed
-- recon/R-A-<world>.md. Markdown, so the baseline is the print itself. What it pins:
--   the plants (every _automation_plan kind, its count and route), so a changed world or generator shows as a diff;
--   every table the build writes: its rows and a fingerprint — the sum of hashtext(row) — so a re-build that is not
--   byte-identical shows too (the determinism the suite proves on the fixture, held on the world).
\pset tuples_only on
\pset format unaligned
SELECT '# R-A — the automation extension of ' || current_database() || ', as of ' || as_of
       || E'\n\nGenerated by data/automation/90-recon.sql — do not edit; refresh with `AUTOMATION_RECON_WRITE=1 just automation-recon <world> <ctx>`.'
  FROM _automation_meta WHERE step = 'build';
SELECT E'\n## Plants (contracts §5)\n\n| kind | keys | expected route |\n|---|---|---|';
SELECT '| ' || kind || ' | ' || count(*) || ' | ' || coalesce(string_agg(DISTINCT expected_route, ' · '), '—') || ' |'
  FROM _automation_plan GROUP BY kind ORDER BY kind;
SELECT E'\n## Tables\n\n| table | rows | fingerprint |\n|---|---|---|';
SELECT '| ' || t || ' | ' || n || ' | ' || f || ' |' FROM (
            SELECT 'sales_order' t, count(*) n, to_hex(coalesce(sum(hashtext(x::text)::bigint), 0)::bigint) f FROM sales_order x
  UNION ALL SELECT 'sales_line', count(*), to_hex(coalesce(sum(hashtext(x::text)::bigint), 0)::bigint) FROM sales_line x
  UNION ALL SELECT 'price_list', count(*), to_hex(coalesce(sum(hashtext(x::text)::bigint), 0)::bigint) FROM price_list x
  UNION ALL SELECT 'customer_price', count(*), to_hex(coalesce(sum(hashtext(x::text)::bigint), 0)::bigint) FROM customer_price x
  UNION ALL SELECT 'invoice', count(*), to_hex(coalesce(sum(hashtext(x::text)::bigint), 0)::bigint) FROM invoice x
  UNION ALL SELECT 'warehouse_outage', count(*), to_hex(coalesce(sum(hashtext(x::text)::bigint), 0)::bigint) FROM warehouse_outage x
  UNION ALL SELECT 'return_request_hdr', count(*), to_hex(coalesce(sum(hashtext(x::text)::bigint), 0)::bigint) FROM return_request_hdr x
  UNION ALL SELECT 'return_request_line', count(*), to_hex(coalesce(sum(hashtext(x::text)::bigint), 0)::bigint) FROM return_request_line x
  UNION ALL SELECT 'return_receipt', count(*), to_hex(coalesce(sum(hashtext(x::text)::bigint), 0)::bigint) FROM return_receipt x
  UNION ALL SELECT 'credit_note', count(*), to_hex(coalesce(sum(hashtext(x::text)::bigint), 0)::bigint) FROM credit_note x
  UNION ALL SELECT 'refund_payment', count(*), to_hex(coalesce(sum(hashtext(x::text)::bigint), 0)::bigint) FROM refund_payment x
  UNION ALL SELECT 'replacement_shipment', count(*), to_hex(coalesce(sum(hashtext(x::text)::bigint), 0)::bigint) FROM replacement_shipment x
  UNION ALL SELECT 'winback_mail', count(*), to_hex(coalesce(sum(hashtext(x::text)::bigint), 0)::bigint) FROM winback_mail x
  UNION ALL SELECT 'customer.c_center_sk', count(c_center_sk), to_hex(coalesce(sum(hashtext(c_customer_sk || ':' || c_center_sk)::bigint), 0)::bigint) FROM customer
  UNION ALL SELECT 'date_dim.d_working_day', count(*) FILTER (WHERE d_working_day), to_hex(coalesce(sum(hashtext(d_date_sk || ':' || d_working_day)::bigint), 0)::bigint) FROM date_dim
  UNION ALL SELECT '_automation_undo (inventory)', count(*), to_hex(coalesce(sum(hashtext(x::text)::bigint), 0)::bigint) FROM _automation_undo x
  UNION ALL SELECT '_automation_events', count(*), to_hex(coalesce(sum(hashtext(x::text)::bigint), 0)::bigint) FROM _automation_events x
  UNION ALL SELECT '_automation_expected', count(*), to_hex(coalesce(sum(hashtext(x::text)::bigint), 0)::bigint) FROM _automation_expected x
) z ORDER BY t;
